/* ---------- Marca / Logótipo original ---------- */
function Brand({ size = "md" }) {
  const dims =
    size === "lg" ? "w-24 h-24" : size === "sm" ? "w-10 h-10" : "w-14 h-14";
  return (
    <div className={`${dims} flex items-center justify-center`}>
      <img
        src={LOGO_MARK}
        alt="Emblema Escola 3S"
        className="w-full h-full object-contain rounded-full"
      />
    </div>
  );
}

function Wordmark() {
  return (
    <div className="flex flex-col items-center select-none">
      <img
        src={LOGO_FULL}
        alt="Escola 3S — Saber, Sentir, Ser"
        className="w-56 h-auto object-contain"
      />
    </div>
  );
}

