const CODIGO_MENTORA = "3S-MENTORA";

async function guardarTelefone(telefone) {
  try {
    const { data } = await supabase.auth.getUser();
    if (!data?.user) return;
    await supabase
      .from("clientes")
      .upsert(
        { user_id: data.user.id, email: data.user.email, telefone, atualizado_em: new Date().toISOString() },
        { onConflict: "user_id" }
      );
  } catch (e) {
    // sem ligação — não bloqueia o resto do fluxo
  }
}

function LoginScreen({ onPedirConfirmacaoEmail, onPedidoRecuperacao }) {
  const [modo, setModo] = useState("entrar"); // "entrar" | "criar"
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [codigo, setCodigo] = useState("");
  const [mostrarCodigo, setMostrarCodigo] = useState(false);
  const [aEnviar, setAEnviar] = useState(false);
  const [erro, setErro] = useState("");

  const submeter = async () => {
    if (!email.trim() || !password.trim()) return;
    setErro("");
    setAEnviar(true);
    try {
      if (modo === "criar") {
        if (codigo.trim() === CODIGO_MENTORA) {
          window.localStorage.setItem("escola3s:pedir-mentora", "1");
        }
        const { data, error } = await supabase.auth.signUp({
          email: email.trim(),
          password: password,
        });
        if (error) throw error;
        if (!data.session) {
          // precisa de confirmar o email antes de poder entrar
          onPedirConfirmacaoEmail(email.trim());
          return;
        }
        // sessão já criada automaticamente (confirmação de email desligada)
      } else {
        const { error } = await supabase.auth.signInWithPassword({
          email: email.trim(),
          password: password,
        });
        if (error) throw error;
      }
    } catch (e) {
      if (String(e.message || "").toLowerCase().includes("invalid login")) {
        setErro("Email ou palavra-passe incorretos.");
      } else if (String(e.message || "").toLowerCase().includes("already registered")) {
        setErro("Já existe uma conta com este email — tenta \"Entrar\".");
      } else {
        setErro("Não foi possível continuar. Verifica os dados e tenta outra vez.");
      }
    } finally {
      setAEnviar(false);
    }
  };

  return (
    <div
      className="min-h-screen w-full flex flex-col items-center justify-center px-8"
      style={{ backgroundColor: palette.cream }}
    >
      <div className="mb-10">
        <Wordmark />
      </div>

      <div className="w-full max-w-xs flex mb-6 rounded-full p-1" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}` }}>
        <button
          onClick={() => { setModo("entrar"); setErro(""); }}
          className="flex-1 rounded-full py-2 text-xs font-medium tracking-wide transition"
          style={modo === "entrar" ? { backgroundColor: palette.navy, color: palette.creamSoft } : { color: palette.navySoft }}
        >
          Entrar
        </button>
        <button
          onClick={() => { setModo("criar"); setErro(""); }}
          className="flex-1 rounded-full py-2 text-xs font-medium tracking-wide transition"
          style={modo === "criar" ? { backgroundColor: palette.navy, color: palette.creamSoft } : { color: palette.navySoft }}
        >
          Criar conta
        </button>
      </div>

      <div className="w-full max-w-xs space-y-4">
        <label className="block">
          <span className="text-xs tracking-widest font-medium" style={{ color: palette.navySoft }}>
            EMAIL
          </span>
          <div
            className="mt-2 flex items-center gap-2 rounded-xl px-4 py-3"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}` }}
          >
            <Mail size={16} style={{ color: palette.gold }} />
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="nome@exemplo.com"
              className="w-full bg-transparent outline-none text-sm"
              style={{ color: palette.ink }}
            />
          </div>
        </label>

        <label className="block">
          <span className="text-xs tracking-widest font-medium" style={{ color: palette.navySoft }}>
            PALAVRA-PASSE
          </span>
          <div
            className="mt-2 flex items-center gap-2 rounded-xl px-4 py-3"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}` }}
          >
            <PenLine size={16} style={{ color: palette.gold }} />
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder={modo === "criar" ? "Cria uma palavra-passe" : "A tua palavra-passe"}
              className="w-full bg-transparent outline-none text-sm"
              style={{ color: palette.ink }}
            />
          </div>
        </label>

        {modo === "criar" && (
          mostrarCodigo ? (
            <label className="block">
              <span className="text-xs tracking-widest font-medium" style={{ color: palette.navySoft }}>
                CÓDIGO DE MENTORA
              </span>
              <div
                className="mt-2 flex items-center gap-2 rounded-xl px-4 py-3"
                style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}` }}
              >
                <PenLine size={16} style={{ color: palette.gold }} />
                <input
                  type="text"
                  value={codigo}
                  onChange={(e) => setCodigo(e.target.value)}
                  placeholder="Código de acesso"
                  className="w-full bg-transparent outline-none text-sm"
                  style={{ color: palette.ink }}
                />
              </div>
            </label>
          ) : (
            <button
              onClick={() => setMostrarCodigo(true)}
              className="text-xs font-medium underline underline-offset-2"
              style={{ color: palette.navySoft }}
            >
              Sou mentora — tenho um código de acesso
            </button>
          )
        )}

        <button
          onClick={submeter}
          disabled={aEnviar}
          className="w-full rounded-full py-3.5 font-medium text-sm tracking-wide flex items-center justify-center gap-2 transition active:scale-[0.98] disabled:opacity-60"
          style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
        >
          {aEnviar ? "Um momento..." : modo === "criar" ? "Criar conta" : "Entrar"}
          {!aEnviar && <ArrowRight size={16} />}
        </button>
        {erro && (
          <p className="text-center text-xs" style={{ color: "#B23A3A" }}>{erro}</p>
        )}
        {modo === "entrar" && (
          <button
            onClick={async () => {
              if (!email.trim()) {
                setErro("Escreve o teu email em cima primeiro.");
                return;
              }
              setErro("");
              setAEnviar(true);
              try {
                const { error } = await supabase.auth.resetPasswordForEmail(email.trim(), {
                  redirectTo: window.location.origin,
                });
                if (error) throw error;
                onPedidoRecuperacao(email.trim());
              } catch (e) {
                setErro("Não foi possível enviar o email de recuperação.");
              } finally {
                setAEnviar(false);
              }
            }}
            className="w-full text-center text-xs font-medium underline underline-offset-2"
            style={{ color: palette.navySoft }}
          >
            Esqueci a palavra-passe
          </button>
        )}
        {modo === "criar" && (
          <p className="text-center text-xs pt-2" style={{ color: palette.navySoft }}>
            Só precisas de confirmar o email uma vez — depois entras sempre com a palavra-passe.
          </p>
        )}
      </div>
    </div>
  );
}

