/* ---------------------------------------------------------
   Disponibilidade para sessões
--------------------------------------------------------- */
function DisponibilidadeScreen({ onBack, disponibilidade, onToggleDia, onAdicionarHora, onRemoverHora, onToggleMes }) {
  const [novaHora, setNovaHora] = useState("");

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="MARCAR SESSÃO" title="Disponibilidade" onBack={onBack} />
      <div className="px-6">
        <p className="text-sm mb-6" style={{ color: palette.navySoft }}>
          Escolhe os dias e as horas em que estás disponível. É isto que aparece
          a quem quiser marcar uma sessão.
        </p>

        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>DIAS LIVRES</p>
        <div className="flex flex-wrap gap-2 mb-8">
          {DIAS_SEMANA.map((dia) => {
            const ativo = disponibilidade.dias.includes(dia);
            return (
              <button
                key={dia}
                onClick={() => onToggleDia(dia)}
                className="rounded-full px-3.5 py-2 text-xs font-medium transition active:scale-[0.97]"
                style={
                  ativo
                    ? { backgroundColor: palette.navy, color: palette.creamSoft }
                    : { backgroundColor: palette.card, color: palette.navySoft, border: `1px solid ${palette.goldSoft}55` }
                }
              >
                {dia}
              </button>
            );
          })}
        </div>

        <p className="text-[11px] tracking-[0.2em] font-medium mb-2" style={{ color: palette.gold }}>MESES</p>
        <p className="text-xs mb-3" style={{ color: palette.navySoft }}>
          Se não escolheres nenhum, fica disponível em todos os meses.
        </p>
        <div className="flex flex-wrap gap-2 mb-8">
          {MESES_COMPLETOS.map((mes) => {
            const ativo = disponibilidade.meses.includes(mes);
            return (
              <button
                key={mes}
                onClick={() => onToggleMes(mes)}
                className="rounded-full px-3.5 py-2 text-xs font-medium transition active:scale-[0.97]"
                style={
                  ativo
                    ? { backgroundColor: palette.navy, color: palette.creamSoft }
                    : { backgroundColor: palette.card, color: palette.navySoft, border: `1px solid ${palette.goldSoft}55` }
                }
              >
                {mes}
              </button>
            );
          })}
        </div>

        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>HORAS</p>
        <div className="flex flex-wrap gap-2 mb-4">
          {disponibilidade.horas.length === 0 && (
            <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não adicionaste nenhuma hora.</p>
          )}
          {disponibilidade.horas.map((h) => (
            <span
              key={h}
              className="flex items-center gap-2 rounded-full pl-3.5 pr-2 py-2 text-xs font-medium"
              style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.navy }}
            >
              {h}
              <button
                onClick={() => onRemoverHora(h)}
                className="w-4 h-4 rounded-full flex items-center justify-center"
                style={{ backgroundColor: `${palette.gold}1F`, color: palette.gold }}
              >
                ×
              </button>
            </span>
          ))}
        </div>

        <div className="flex gap-2">
          <select
            value={novaHora}
            onChange={(e) => setNovaHora(e.target.value)}
            className="flex-1 rounded-xl px-4 py-2.5 text-sm outline-none"
            style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          >
            <option value="">Escolhe uma hora</option>
            {Array.from({ length: 27 }, (_, i) => {
              const totalMin = 8 * 60 + i * 30; // das 8:00 às 21:00, de 30 em 30 min
              const h = String(Math.floor(totalMin / 60)).padStart(2, "0");
              const m = String(totalMin % 60).padStart(2, "0");
              const valor = `${h}:${m}`;
              return <option key={valor} value={valor}>{valor}</option>;
            })}
          </select>
          <button
            onClick={() => {
              if (novaHora) {
                onAdicionarHora(novaHora);
                setNovaHora("");
              }
            }}
            className="rounded-xl px-4 py-2.5 text-sm font-medium tracking-wide"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            Adicionar
          </button>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Painel da Mentora
--------------------------------------------------------- */
function ConteudoDoMes({ mes }) {
  const [aberto, setAberto] = useState(false);
  const formacao = mes.formacaoId ? cursos.find((c) => c.id === mes.formacaoId) : null;
  const materiaisDoMes = (mes.materialPrincipalIds || [])
    .map((id) => materiais.find((m) => m.id === id))
    .filter(Boolean);

  return (
    <div className="rounded-2xl overflow-hidden" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
      <button
        onClick={() => setAberto((a) => !a)}
        className="w-full flex items-center justify-between px-4 py-3.5 text-left"
      >
        <div>
          <p className="text-[10px] tracking-[0.2em] font-medium" style={{ color: palette.gold }}>{mes.mes.toUpperCase()}</p>
          <p className="font-serif text-lg leading-snug" style={{ color: palette.navy }}>{mes.tema}</p>
        </div>
        <ChevronRight
          size={18}
          style={{ color: palette.navySoft, transform: aberto ? "rotate(90deg)" : "none", transition: "transform 0.15s" }}
        />
      </button>

      {aberto && (
        <div className="px-4 pb-4 space-y-4">
          {mes.livro && (
            <div>
              <p className="text-[10px] tracking-[0.2em] font-medium mb-1" style={{ color: palette.navySoft }}>LIVRO</p>
              <p className="text-sm" style={{ color: palette.ink }}>{mes.livro}</p>
            </div>
          )}

          {formacao && (
            <div>
              <p className="text-[10px] tracking-[0.2em] font-medium mb-1.5" style={{ color: palette.navySoft }}>CURSO — {formacao.titulo.toUpperCase()}</p>
              {formacao.aulas && formacao.aulas.length > 0 ? (
                <div className="space-y-1.5">
                  {formacao.aulas.map((aula, i) => (
                    <p key={i} className="text-xs leading-relaxed" style={{ color: palette.ink }}>
                      <strong style={{ color: palette.navy }}>{i + 1}. {aula.titulo}</strong> — {aula.descricao}
                    </p>
                  ))}
                </div>
              ) : (
                <p className="text-xs" style={{ color: palette.ink }}>{formacao.promessa}</p>
              )}
            </div>
          )}

          <div>
            <p className="text-[10px] tracking-[0.2em] font-medium mb-1" style={{ color: palette.navySoft }}>PERGUNTA DO MÊS</p>
            <p className="text-sm" style={{ color: palette.ink }}>{mes.perguntaPrincipal}</p>
          </div>

          <div>
            <p className="text-[10px] tracking-[0.2em] font-medium mb-1.5" style={{ color: palette.navySoft }}>PERGUNTAS DE REFLEXÃO</p>
            <div className="space-y-1">
              {mes.perguntasReflexao.map((p, i) => (
                <p key={i} className="text-xs leading-relaxed" style={{ color: palette.ink }}>· {p}</p>
              ))}
            </div>
          </div>

          <div>
            <p className="text-[10px] tracking-[0.2em] font-medium mb-1" style={{ color: palette.navySoft }}>DESAFIO 3S — {mes.desafio.titulo.toUpperCase()}</p>
            <p className="text-xs leading-relaxed" style={{ color: palette.ink }}>{mes.desafio.descricao}</p>
          </div>

          {materiaisDoMes.length > 0 && (
            <div>
              <p className="text-[10px] tracking-[0.2em] font-medium mb-1.5" style={{ color: palette.navySoft }}>MATERIAL PRINCIPAL</p>
              <div className="space-y-1">
                {materiaisDoMes.map((m) => (
                  <p key={m.id} className="text-xs" style={{ color: palette.ink }}>{m.titulo} · {m.formato} · {m.preco}</p>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function DashboardMentoraScreen({ onBack, onAbrirCliente }) {
  const [carregando, setCarregando] = useState(true);
  const [clientes, setClientes] = useState([]);
  const [progressos, setProgressos] = useState({});
  const [pagamentos, setPagamentos] = useState([]);
  const [pedidos, setPedidos] = useState([]);
  const [marcacoes, setMarcacoes] = useState([]);
  const [aProcessar, setAProcessar] = useState(null);
  const [meuUserId, setMeuUserId] = useState(null);
  const [souDona, setSouDona] = useState(false);

  const carregarTudo = async () => {
    setCarregando(true);
    const { data: sessaoAtual } = await supabase.auth.getSession();
    const userId = sessaoAtual?.session?.user?.id || null;
    setMeuUserId(userId);

    const { data: meuProgresso } = await supabase
      .from("user_progress")
      .select("data")
      .eq("user_id", userId)
      .maybeSingle();
    const ehDona = meuProgresso?.data?.papel === "dona";
    setSouDona(ehDona);

    let consultaMarcacoes = supabase.from("marcacoes").select("*").eq("estado", "confirmada").order("criado_em", { ascending: false });
    if (!ehDona) consultaMarcacoes = consultaMarcacoes.eq("mentor_user_id", userId);

    const [rClientes, rProgressos, rPagamentos, rPedidos, rMarcacoes] = await Promise.all([
      supabase.from("clientes").select("*").order("criado_em", { ascending: false }),
      supabase.from("user_progress").select("user_id, data"),
      supabase.from("pagamentos").select("*").order("criado_em", { ascending: false }),
      supabase.from("pedidos_mentora").select("*").eq("estado", "pendente").order("criado_em", { ascending: true }),
      consultaMarcacoes,
    ]);

    setClientes(rClientes.data || []);
    const mapaProgresso = {};
    (rProgressos.data || []).forEach((p) => { mapaProgresso[p.user_id] = p.data || {}; });
    setProgressos(mapaProgresso);
    setPagamentos(rPagamentos.data || []);
    setPedidos(rPedidos.data || []);
    setMarcacoes(rMarcacoes.data || []);
    setCarregando(false);
  };

  useEffect(() => { carregarTudo(); }, []);

  const decidirPedido = async (pedidoId, acao) => {
    setAProcessar(pedidoId);
    try {
      const { data: sessaoAtual } = await supabase.auth.getSession();
      await fetch(`https://hspekqrhttxeckghtryi.supabase.co/functions/v1/aprovar-mentora`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${sessaoAtual.session.access_token}`,
        },
        body: JSON.stringify({ pedidoId, acao }),
      });
      await carregarTudo();
    } catch (e) {
      // falha silenciosa — a lista simplesmente não se atualiza
    }
    setAProcessar(null);
  };

  const totalInscritosComunidade = Object.values(progressos).filter((p) => p.comunidadeDesbloqueada).length;
  const totalPagamentosPagos = pagamentos.filter((p) => p.estado === "pago").length;
  const valorTotal = pagamentos.filter((p) => p.estado === "pago").reduce((soma, p) => soma + Number(p.valor || 0), 0);

  if (carregando) {
    return (
      <div className="pb-28">
        <SectionHeader eyebrow="VISÃO DA ESCOLA" title="Dashboard" onBack={onBack} />
        <p className="px-6 text-sm" style={{ color: palette.navySoft }}>A carregar...</p>
      </div>
    );
  }

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="VISÃO DA ESCOLA" title="Dashboard" onBack={onBack} />

      <div className="px-6 grid grid-cols-3 gap-3 mb-8">
        <div className="rounded-2xl px-3 py-4 text-center" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          <p className="font-serif text-2xl" style={{ color: palette.navy }}>{clientes.length}</p>
          <p className="text-[10px] tracking-wide mt-1" style={{ color: palette.navySoft }}>SUBSCRITORES</p>
        </div>
        <div className="rounded-2xl px-3 py-4 text-center" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          <p className="font-serif text-2xl" style={{ color: palette.navy }}>{totalInscritosComunidade}</p>
          <p className="text-[10px] tracking-wide mt-1" style={{ color: palette.navySoft }}>NA COMUNIDADE</p>
        </div>
        <div className="rounded-2xl px-3 py-4 text-center" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          <p className="font-serif text-2xl" style={{ color: palette.navy }}>{valorTotal.toFixed(2)}€</p>
          <p className="text-[10px] tracking-wide mt-1" style={{ color: palette.navySoft }}>PAGAMENTOS ({totalPagamentosPagos})</p>
        </div>
      </div>

      {pedidos.length > 0 && (
        <div className="px-6 mb-8">
          <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>PEDIDOS DE ACESSO COMO MENTORA</p>
          <div className="space-y-2">
            {pedidos.map((p) => (
              <div key={p.id} className="rounded-xl px-4 py-3" style={{ backgroundColor: `${palette.gold}1F`, border: `1px solid ${palette.gold}` }}>
                <p className="text-sm" style={{ color: palette.navy }}>{p.email}</p>
                <div className="flex gap-2 mt-2">
                  <button
                    disabled={aProcessar === p.id}
                    onClick={() => decidirPedido(p.id, "aprovar")}
                    className="flex-1 rounded-lg py-2 text-xs font-medium"
                    style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
                  >
                    Aprovar
                  </button>
                  <button
                    disabled={aProcessar === p.id}
                    onClick={() => decidirPedido(p.id, "rejeitar")}
                    className="flex-1 rounded-lg py-2 text-xs font-medium"
                    style={{ backgroundColor: "transparent", color: palette.navySoft, border: `1px solid ${palette.goldSoft}` }}
                  >
                    Rejeitar
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="px-6 mb-8">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>{souDona ? "TODAS AS MARCAÇÕES DA ESCOLA" : "AS TUAS MARCAÇÕES"}</p>
        {marcacoes.length === 0 && (
          <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há sessões marcadas.</p>
        )}
        <div className="space-y-2">
          {marcacoes.map((m) => {
            const cliente = clientes.find((c) => c.user_id === m.user_id);
            const mentora = clientes.find((c) => c.user_id === m.mentor_user_id);
            return (
              <div key={m.id} className="rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                <div className="flex items-center justify-between">
                  <p className="text-sm font-medium" style={{ color: palette.ink }}>{m.titulo}</p>
                  <p className="text-xs font-medium" style={{ color: palette.gold }}>{formatarChaveHorario(m.horario)}</p>
                </div>
                <p className="text-xs mt-1" style={{ color: palette.navySoft }}>
                  {cliente ? cliente.email : "email desconhecido"}{cliente?.telefone ? ` · ${cliente.telefone}` : ""}
                </p>
                {souDona && mentora && (
                  <p className="text-[10px] mt-1 tracking-wide" style={{ color: palette.gold }}>COM {mentora.email.toUpperCase()}</p>
                )}
              </div>
            );
          })}
        </div>
      </div>

      <div className="px-6 mb-8">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>VENDAS</p>
        {pagamentos.length === 0 && (
          <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há vendas registadas.</p>
        )}
        <div className="space-y-2">
          {pagamentos.map((p) => {
            const cliente = clientes.find((c) => c.user_id === p.user_id);
            return (
              <div key={p.id} className="rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                <div className="flex items-center justify-between">
                  <p className="text-sm font-medium" style={{ color: palette.ink }}>{p.descricao}</p>
                  <p className="font-serif text-sm" style={{ color: palette.gold }}>{Number(p.valor).toFixed(2)}€</p>
                </div>
                <div className="flex items-center justify-between mt-1">
                  <p className="text-xs" style={{ color: palette.navySoft }}>
                    {cliente ? cliente.email : "email desconhecido"}
                  </p>
                  <span
                    className="text-[10px] tracking-wide font-medium"
                    style={{ color: p.estado === "pago" ? palette.gold : palette.navySoft }}
                  >
                    {p.estado.toUpperCase()}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="px-6">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>FICHA DE CLIENTES</p>
        {clientes.length === 0 && (
          <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há subscritores.</p>
        )}
        <div className="space-y-2">
          {clientes.map((c) => {
            const prog = progressos[c.user_id] || {};
            const pagamentosDaPessoa = pagamentos.filter((p) => p.user_id === c.user_id);
            return (
              <button
                key={c.user_id}
                onClick={() => onAbrirCliente(c)}
                className="w-full text-left rounded-xl px-4 py-3 transition active:scale-[0.99]"
                style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
              >
                <div className="flex items-center justify-between">
                  <p className="text-sm font-medium" style={{ color: palette.ink }}>{c.nome || c.email}</p>
                  {(prog.papel === "mentora" || prog.papel === "dona") && (
                    <span className="text-[10px] tracking-wide font-medium" style={{ color: palette.gold }}>{prog.papel === "dona" ? "DONA" : "MENTORA"}</span>
                  )}
                </div>
                <p className="text-xs mt-1" style={{ color: palette.navySoft }}>
                  {c.nome ? c.email + " · " : ""}
                  {c.telefone || "sem telemóvel"} · {prog.comunidadeDesbloqueada ? "na Comunidade" : "sem Comunidade"} · {pagamentosDaPessoa.length} pagamento(s)
                </p>
                <p className="text-[10px] mt-1.5 tracking-wide" style={{ color: palette.gold }}>VER FICHA COMPLETA →</p>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function FichaClienteScreen({ cliente, onBack, onNomeAtualizado }) {
  const [carregando, setCarregando] = useState(true);
  const [nome, setNome] = useState(cliente.nome || "");
  const [aGuardarNome, setAGuardarNome] = useState(false);
  const [anamnese, setAnamnese] = useState({
    objetivos: "", contexto_de_vida: "", historico_relevante: "", expectativas: "", notas_gerais: "",
  });
  const [aGuardar, setAGuardar] = useState(false);
  const [guardado, setGuardado] = useState(false);
  const [notas, setNotas] = useState([]);
  const [novaNota, setNovaNota] = useState("");
  const [tituloNota, setTituloNota] = useState("");
  const [aGuardarNota, setAGuardarNota] = useState(false);

  const carregar = async () => {
    setCarregando(true);
    const [rAnamnese, rNotas] = await Promise.all([
      supabase.from("fichas_anamnese").select("*").eq("user_id", cliente.user_id).maybeSingle(),
      supabase.from("notas_sessao").select("*").eq("user_id", cliente.user_id).order("criado_em", { ascending: false }),
    ]);
    if (rAnamnese.data) {
      setAnamnese({
        objetivos: rAnamnese.data.objetivos || "",
        contexto_de_vida: rAnamnese.data.contexto_de_vida || "",
        historico_relevante: rAnamnese.data.historico_relevante || "",
        expectativas: rAnamnese.data.expectativas || "",
        notas_gerais: rAnamnese.data.notas_gerais || "",
      });
    }
    setNotas(rNotas.data || []);
    setCarregando(false);
  };

  useEffect(() => { carregar(); }, [cliente.user_id]);

  const guardarNome = async () => {
    setAGuardarNome(true);
    await supabase
      .from("clientes")
      .update({ nome: nome.trim(), atualizado_em: new Date().toISOString() })
      .eq("user_id", cliente.user_id);
    setAGuardarNome(false);
    if (onNomeAtualizado) onNomeAtualizado(cliente.user_id, nome.trim());
  };

  const guardarAnamnese = async () => {
    setAGuardar(true);
    setGuardado(false);
    const { data: sessaoAtual } = await supabase.auth.getSession();
    await supabase
      .from("fichas_anamnese")
      .upsert(
        { user_id: cliente.user_id, ...anamnese, atualizado_em: new Date().toISOString(), atualizado_por: sessaoAtual.session.user.id },
        { onConflict: "user_id" }
      );
    setAGuardar(false);
    setGuardado(true);
  };

  const adicionarNota = async () => {
    if (!novaNota.trim()) return;
    setAGuardarNota(true);
    const { data: sessaoAtual } = await supabase.auth.getSession();
    await supabase.from("notas_sessao").insert({
      user_id: cliente.user_id,
      mentor_user_id: sessaoAtual.session.user.id,
      titulo: tituloNota.trim(),
      conteudo: novaNota.trim(),
    });
    setNovaNota("");
    setTituloNota("");
    setAGuardarNota(false);
    carregar();
  };

  const campo = (chave, label, linhas = 3) => (
    <div className="mb-4">
      <p className="text-[11px] tracking-[0.15em] font-medium mb-1.5" style={{ color: palette.gold }}>{label.toUpperCase()}</p>
      <textarea
        value={anamnese[chave]}
        onChange={(e) => setAnamnese((a) => ({ ...a, [chave]: e.target.value }))}
        rows={linhas}
        className="w-full rounded-xl px-3.5 py-3 text-sm outline-none resize-none"
        style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
      />
    </div>
  );

  if (carregando) {
    return (
      <div className="pb-28">
        <SectionHeader eyebrow="FICHA DE CLIENTE" title={cliente.nome || cliente.email} onBack={onBack} />
        <p className="px-6 text-sm" style={{ color: palette.navySoft }}>A carregar...</p>
      </div>
    );
  }

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="FICHA DE CLIENTE" title={nome || cliente.email} onBack={onBack} />

      <div className="px-6 mb-6">
        <p className="text-[11px] tracking-[0.15em] font-medium mb-1.5" style={{ color: palette.gold }}>NOME</p>
        <div className="flex gap-2">
          <input
            type="text"
            value={nome}
            onChange={(e) => setNome(e.target.value)}
            placeholder="Nome do cliente"
            className="flex-1 rounded-xl px-3.5 py-2.5 text-sm outline-none"
            style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          />
          <button
            onClick={guardarNome}
            disabled={aGuardarNome}
            className="rounded-xl px-4 text-xs font-medium disabled:opacity-60"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            {aGuardarNome ? "..." : "Guardar"}
          </button>
        </div>
        <p className="text-xs mt-2" style={{ color: palette.navySoft }}>{cliente.email} · {cliente.telefone || "sem telemóvel registado"}</p>
      </div>

      <div className="px-6 mb-8">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>FICHA DE ANAMNESE</p>
        <div className="rounded-2xl px-4 py-4" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          {campo("objetivos", "Objetivos")}
          {campo("contexto_de_vida", "Contexto de vida")}
          {campo("historico_relevante", "Histórico relevante")}
          {campo("expectativas", "Expectativas")}
          {campo("notas_gerais", "Notas gerais", 4)}
          <button
            onClick={guardarAnamnese}
            disabled={aGuardar}
            className="w-full rounded-full py-2.5 text-xs font-medium tracking-wide disabled:opacity-60"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            {aGuardar ? "A guardar..." : "Guardar ficha"}
          </button>
          {guardado && <p className="text-center text-xs mt-2" style={{ color: palette.gold }}>Guardado</p>}
        </div>
      </div>

      <div className="px-6">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>NOTAS DE SESSÃO</p>

        <div className="rounded-2xl px-4 py-4 mb-4" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          <input
            type="text"
            value={tituloNota}
            onChange={(e) => setTituloNota(e.target.value)}
            placeholder="Título (ex: Sessão 12 set)"
            className="w-full rounded-xl px-3.5 py-2.5 text-sm outline-none mb-2"
            style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          />
          <textarea
            value={novaNota}
            onChange={(e) => setNovaNota(e.target.value)}
            placeholder="O que aconteceu nesta sessão, observações, próximos passos..."
            rows={4}
            className="w-full rounded-xl px-3.5 py-3 text-sm outline-none resize-none mb-2"
            style={{ backgroundColor: palette.creamSoft, border: `1px solid ${palette.goldSoft}55`, color: palette.ink }}
          />
          <button
            onClick={adicionarNota}
            disabled={aGuardarNota || !novaNota.trim()}
            className="w-full rounded-full py-2.5 text-xs font-medium tracking-wide disabled:opacity-60"
            style={{ backgroundColor: palette.navy, color: palette.creamSoft }}
          >
            {aGuardarNota ? "A adicionar..." : "Adicionar nota"}
          </button>
        </div>

        {notas.length === 0 ? (
          <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há notas de sessão.</p>
        ) : (
          <div className="space-y-2">
            {notas.map((n) => (
              <div key={n.id} className="rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                <div className="flex items-center justify-between mb-1">
                  <p className="text-sm font-medium" style={{ color: palette.navy }}>{n.titulo || "Nota"}</p>
                  <p className="text-[10px]" style={{ color: palette.navySoft }}>
                    {new Date(n.criado_em).toLocaleDateString("pt-PT")}
                  </p>
                </div>
                <p className="text-sm leading-relaxed" style={{ color: palette.ink }}>{n.conteudo}</p>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

function PainelMentoraScreen({ onBack, progresso, onVerDashboard }) {
  const totalInscricoes = Object.values(progresso.inscricoesWorkshops).filter(Boolean).length;
  const totalMateriais = Object.values(progresso.materiaisDesbloqueados).filter(Boolean).length;
  const totalConcluidos = Object.values(progresso.cursosConcluidos).filter(Boolean).length;

  return (
    <div className="pb-28">
      <SectionHeader eyebrow="VISÃO DA ESCOLA" title="Painel da Mentora" onBack={onBack} />

      <div className="px-6 mb-6">
        <button
          onClick={onVerDashboard}
          className="w-full flex items-center justify-between rounded-2xl px-5 py-4"
          style={{ backgroundColor: palette.navy }}
        >
          <div className="text-left">
            <p className="font-serif text-lg" style={{ color: palette.creamSoft }}>Dashboard de Subscritores</p>
            <p className="text-xs mt-0.5" style={{ color: palette.goldSoft }}>Clientes, telefones, pagamentos e pedidos de acesso</p>
          </div>
          <ChevronRight size={18} style={{ color: palette.gold }} />
        </button>
      </div>

      <div className="px-6 mb-8">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>CONTEÚDO POR MÊS</p>
        <div className="space-y-2">
          {comunidadeMeses.map((m) => (
            <ConteudoDoMes key={m.mes} mes={m} />
          ))}
        </div>
      </div>

      <div className="px-6 grid grid-cols-3 gap-3 mb-8">
        <div className="rounded-2xl px-3 py-4 text-center" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          <p className="font-serif text-2xl" style={{ color: palette.navy }}>{totalInscricoes}</p>
          <p className="text-[10px] tracking-wide mt-1" style={{ color: palette.navySoft }}>INSCRIÇÕES WORKSHOPS</p>
        </div>
        <div className="rounded-2xl px-3 py-4 text-center" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          <p className="font-serif text-2xl" style={{ color: palette.navy }}>{progresso.sessoesMarcadas.length}</p>
          <p className="text-[10px] tracking-wide mt-1" style={{ color: palette.navySoft }}>SESSÕES MARCADAS</p>
        </div>
        <div className="rounded-2xl px-3 py-4 text-center" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
          <p className="font-serif text-2xl" style={{ color: palette.navy }}>{totalMateriais}</p>
          <p className="text-[10px] tracking-wide mt-1" style={{ color: palette.navySoft }}>MATERIAIS DESBLOQUEADOS</p>
        </div>
      </div>

      <div className="px-6 mb-8">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>SESSÕES MARCADAS</p>
        {progresso.sessoesMarcadas.length === 0 ? (
          <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não há sessões marcadas.</p>
        ) : (
          <div className="space-y-2">
            {progresso.sessoesMarcadas.map((s, i) => (
              <div key={i} className="flex items-center gap-3 rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                <PenLine size={16} style={{ color: palette.gold }} />
                <div className="flex-1 min-w-0">
                  <p className="text-sm" style={{ color: palette.ink }}>{s.titulo}</p>
                  <p className="text-xs" style={{ color: palette.navySoft }}>{s.horario}</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="px-6 mb-8">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>INSCRIÇÕES POR WORKSHOP</p>
        <div className="space-y-2">
          {workshops.map((w) => {
            const inscrito = Boolean(progresso.inscricoesWorkshops[w.id]);
            return (
              <div key={w.id} className="flex items-center gap-3 rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                <Calendar size={16} style={{ color: inscrito ? palette.gold : palette.navySoft }} />
                <p className="text-sm flex-1" style={{ color: palette.ink }}>{w.titulo}</p>
                <span className="text-xs font-medium" style={{ color: inscrito ? palette.gold : palette.navySoft }}>
                  {inscrito ? "1 inscrição" : "0 inscrições"}
                </span>
              </div>
            );
          })}
        </div>
      </div>

      <div className="px-6">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>DISPONIBILIDADE ATUAL</p>
        {progresso.disponibilidade.dias.length === 0 || progresso.disponibilidade.horas.length === 0 ? (
          <p className="text-sm" style={{ color: palette.navySoft }}>Ainda não definiste dias/horas para sessões.</p>
        ) : (
          <p className="text-sm leading-relaxed" style={{ color: palette.ink }}>
            {progresso.disponibilidade.dias.join(", ")} · {progresso.disponibilidade.horas.join(", ")}
          </p>
        )}
      </div>

      <div className="px-6 mt-8">
        <p className="text-[11px] tracking-[0.2em] font-medium mb-3" style={{ color: palette.gold }}>COMUNIDADE 3S</p>
        <div
          className="flex items-center gap-3 rounded-xl px-4 py-3 mb-3"
          style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
        >
          <Users size={16} style={{ color: progresso.comunidadeDesbloqueada ? palette.gold : palette.navySoft }} />
          <p className="text-sm flex-1" style={{ color: palette.ink }}>Acesso à Comunidade</p>
          <span className="text-xs font-medium" style={{ color: progresso.comunidadeDesbloqueada ? palette.gold : palette.navySoft }}>
            {progresso.comunidadeDesbloqueada ? "Desbloqueado" : "Por desbloquear"}
          </span>
        </div>

        <p className="text-xs tracking-wide font-medium mb-2" style={{ color: palette.navySoft }}>REFLEXÕES GUARDADAS POR MÊS</p>
        <div className="space-y-2">
          {comunidadeMeses.map((m) => {
            const texto = progresso.reflexoesComunidade[m.mes];
            return (
              <div key={m.mes} className="rounded-xl px-4 py-3" style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}>
                <div className="flex items-center justify-between">
                  <p className="text-xs font-medium" style={{ color: palette.navy }}>{m.mes}</p>
                  {texto ? (
                    <CheckCircle2 size={14} style={{ color: palette.gold }} />
                  ) : (
                    <span className="text-[10px]" style={{ color: palette.navySoft }}>sem reflexão</span>
                  )}
                </div>
                {texto && (
                  <p className="text-sm mt-1 leading-relaxed" style={{ color: palette.ink }}>"{texto}"</p>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function PerfilScreen({ onVerAreaAluno, onVerDisponibilidade, onVerPainelMentora, papel, onToggleMentora, onSair, email }) {
  const iniciais = email ? email.slice(0, 2).toUpperCase() : "?";
  return (
    <div className="pb-28">
      <SectionHeader eyebrow="A TUA CONTA" title="Perfil" />
      <div className="px-6 flex flex-col items-center text-center mt-2 mb-8">
        <div className="w-20 h-20 rounded-full flex items-center justify-center font-serif text-2xl" style={{ backgroundColor: palette.navy, color: palette.creamSoft }}>
          {iniciais}
        </div>
        <p className="text-xs mt-3" style={{ color: palette.navySoft }}>{email}</p>
      </div>
      <div className="px-6 mb-6">
        <button
          onClick={onToggleMentora}
          disabled={papel === "dona"}
          className="w-full flex items-center justify-between rounded-xl px-4 py-3.5 text-left disabled:opacity-70"
          style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
        >
          <div>
            <p className="text-sm font-medium" style={{ color: palette.ink }}>
              {papel === "dona" ? "És a dona da escola" : "Estou a usar como Mentora"}
            </p>
            <p className="text-xs mt-0.5" style={{ color: palette.navySoft }}>
              {papel === "dona" ? "Vês tudo — todas as mentoras, clientes e marcações" : "Ativa para veres o Painel da Mentora"}
            </p>
          </div>
          <span
            className="w-11 h-6 rounded-full flex items-center px-0.5 shrink-0 transition"
            style={{
              backgroundColor: (papel === "mentora" || papel === "dona") ? palette.navy : palette.goldSoft,
              justifyContent: (papel === "mentora" || papel === "dona") ? "flex-end" : "flex-start",
            }}
          >
            <span className="w-5 h-5 rounded-full" style={{ backgroundColor: palette.creamSoft }} />
          </span>
        </button>
      </div>

      <div className="px-6 space-y-2.5">
        {(papel === "mentora" || papel === "dona") && (
          <button
            onClick={onVerPainelMentora}
            className="w-full flex items-center justify-between rounded-xl px-4 py-3.5 text-left"
            style={{ backgroundColor: palette.navy }}
          >
            <span className="text-sm font-medium" style={{ color: palette.creamSoft }}>Painel da Mentora</span>
            <ChevronRight size={16} style={{ color: palette.gold }} />
          </button>
        )}
        <button
          onClick={onVerAreaAluno}
          className="w-full flex items-center justify-between rounded-xl px-4 py-3.5 text-left"
          style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
        >
          <span className="text-sm font-medium" style={{ color: palette.ink }}>Ver progresso e conteúdos</span>
          <ChevronRight size={16} style={{ color: palette.navySoft }} />
        </button>
        <button
          onClick={onVerDisponibilidade}
          className="w-full flex items-center justify-between rounded-xl px-4 py-3.5 text-left"
          style={{ backgroundColor: palette.card, border: `1px solid ${palette.goldSoft}55` }}
        >
          <span className="text-sm font-medium" style={{ color: palette.ink }}>Gerir disponibilidade para sessões</span>
          <ChevronRight size={16} style={{ color: palette.navySoft }} />
        </button>
        <button
          onClick={onSair}
          className="w-full flex items-center justify-center gap-2 rounded-xl px-4 py-3.5 text-sm font-medium"
          style={{ color: palette.navySoft, border: `1px solid ${palette.goldSoft}55` }}
        >
          <LogOut size={16} />
          Sair
        </button>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   Navegação inferior
--------------------------------------------------------- */
function BottomNav({ active, onChange }) {
  const items = [
    { key: "inicio", label: "Início", icon: Home },
    { key: "explorar", label: "Explorar", icon: Compass },
    { key: "agenda", label: "Agenda", icon: Calendar },
    { key: "perfil", label: "Perfil", icon: User },
  ];
  return (
    <div className="fixed bottom-0 left-0 right-0 flex justify-center">
      <div
        className="w-full max-w-md flex items-stretch px-2"
        style={{ backgroundColor: palette.card, borderTop: `1px solid ${palette.goldSoft}55` }}
      >
        {items.map(({ key, label, icon: Icon }) => {
          const isActive = active === key;
          return (
            <button key={key} onClick={() => onChange(key)} className="flex-1 flex flex-col items-center justify-center gap-1 py-2.5">
              <Icon size={20} strokeWidth={isActive ? 2.4 : 1.8} style={{ color: isActive ? palette.navy : palette.navySoft, opacity: isActive ? 1 : 0.55 }} />
              <span className="text-[10px] font-medium tracking-wide" style={{ color: isActive ? palette.navy : palette.navySoft, opacity: isActive ? 1 : 0.55 }}>
                {label}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

/* ---------------------------------------------------------
   App
--------------------------------------------------------- */
export default function App() {
  const [session, setSession] = useState(null);
  const [sessaoCarregada, setSessaoCarregada] = useState(false);
  const [emailEnviado, setEmailEnviado] = useState(null);
  const [emailRecuperacao, setEmailRecuperacao] = useState(null);
  const [modoNovaPassword, setModoNovaPassword] = useState(false);
  const [tab, setTab] = useState("inicio");
  const [secao, setSecao] = useState(null);
  const [cursoAberto, setCursoAberto] = useState(null);
  const [clienteAberto, setClienteAberto] = useState(null);
  const [certificadoAberto, setCertificadoAberto] = useState(null);
  const [conversaAberta, setConversaAberta] = useState(null);

  const [progresso, setProgresso] = useState({
    inscricoesWorkshops: {},
    sessoesMarcadas: [],
    materiaisDesbloqueados: {},
    cursosConcluidos: {},
    comunidadeDesbloqueada: false,
    disponibilidade: { dias: [], horas: [], meses: [] },
    papel: "aluno",
    reflexoesComunidade: {},
  });
  const [carregado, setCarregado] = useState(false);

  // Sessão de autenticação (email + password)
  useEffect(() => {
    let cancelado = false;
    supabase.auth.getSession().then(({ data }) => {
      if (!cancelado) {
        setSession(data.session);
        setSessaoCarregada(true);
      }
    });
    const { data: listener } = supabase.auth.onAuthStateChange((event, novaSessao) => {
      if (event === "PASSWORD_RECOVERY") {
        setModoNovaPassword(true);
      }
      setSession(novaSessao);
      setSessaoCarregada(true);
    });
    return () => {
      cancelado = true;
      listener.subscription.unsubscribe();
    };
  }, []);

  // Carrega o progresso da pessoa a partir da base de dados, assim que há sessão
  useEffect(() => {
    if (!session) {
      setCarregado(false);
      return;
    }
    let cancelado = false;
    (async () => {
      try {
        const { data, error } = await supabase
          .from("user_progress")
          .select("data")
          .eq("user_id", session.user.id)
          .maybeSingle();

        if (!cancelado) {
          const salvo = (!error && data && data.data) ? data.data : {};

          setProgresso((p) => ({
            ...p,
            ...salvo,
            disponibilidade: { ...p.disponibilidade, ...(salvo.disponibilidade || {}) },
            reflexoesComunidade: { ...p.reflexoesComunidade, ...(salvo.reflexoesComunidade || {}) },
            papel: salvo.papel || p.papel,
          }));
        }

        // Garante que existe ficha de cliente para esta pessoa
        await supabase
          .from("clientes")
          .upsert(
            { user_id: session.user.id, email: session.user.email, atualizado_em: new Date().toISOString() },
            { onConflict: "user_id", ignoreDuplicates: false }
          );

        // Se veio de um login com o código de mentora, cria o pedido (só uma vez)
        let pedirMentora = null;
        try {
          pedirMentora = window.localStorage.getItem("escola3s:pedir-mentora");
          if (pedirMentora) window.localStorage.removeItem("escola3s:pedir-mentora");
        } catch (e) {}

        if (pedirMentora) {
          await supabase
            .from("pedidos_mentora")
            .upsert(
              { user_id: session.user.id, email: session.user.email },
              { onConflict: "user_id", ignoreDuplicates: true }
            );
        }
      } catch (e) {
        // sem dados guardados ainda — arranca do zero
      }
      if (!cancelado) setCarregado(true);
    })();
    return () => { cancelado = true; };
  }, [session]);

  // Guarda o progresso na base de dados sempre que muda
  useEffect(() => {
    if (!carregado || !session) return;
    supabase
      .from("user_progress")
      .upsert({ user_id: session.user.id, data: progresso, updated_at: new Date().toISOString() })
      .then(() => {})
      .catch(() => {});
  }, [progresso, carregado, session]);

  const toggleInscricao = (id) =>
    setProgresso((p) => ({
      ...p,
      inscricoesWorkshops: { ...p.inscricoesWorkshops, [id]: !p.inscricoesWorkshops[id] },
    }));

  const registarSessao = (sessao) =>
    setProgresso((p) => ({ ...p, sessoesMarcadas: [...p.sessoesMarcadas, sessao] }));

  const desbloquearMaterial = (id) =>
    setProgresso((p) => ({
      ...p,
      materiaisDesbloqueados: { ...p.materiaisDesbloqueados, [id]: true },
    }));

  const toggleConcluido = (id) =>
    setProgresso((p) => ({
      ...p,
      cursosConcluidos: {
        ...p.cursosConcluidos,
        [id]: p.cursosConcluidos[id] ? false : new Date().toISOString(),
      },
    }));

  const desbloquearComunidade = () =>
    setProgresso((p) => ({ ...p, comunidadeDesbloqueada: true }));

  const toggleDiaDisponivel = (dia) =>
    setProgresso((p) => {
      const jaTem = p.disponibilidade.dias.includes(dia);
      const dias = jaTem
        ? p.disponibilidade.dias.filter((d) => d !== dia)
        : [...p.disponibilidade.dias, dia];
      return { ...p, disponibilidade: { ...p.disponibilidade, dias } };
    });

  const toggleMesDisponivel = (mes) =>
    setProgresso((p) => {
      const jaTem = p.disponibilidade.meses.includes(mes);
      const meses = jaTem
        ? p.disponibilidade.meses.filter((m) => m !== mes)
        : [...p.disponibilidade.meses, mes];
      return { ...p, disponibilidade: { ...p.disponibilidade, meses } };
    });

  const adicionarHora = (hora) =>
    setProgresso((p) => {
      if (p.disponibilidade.horas.includes(hora)) return p;
      return { ...p, disponibilidade: { ...p.disponibilidade, horas: [...p.disponibilidade.horas, hora].sort() } };
    });

  const removerHora = (hora) =>
    setProgresso((p) => ({
      ...p,
      disponibilidade: { ...p.disponibilidade, horas: p.disponibilidade.horas.filter((h) => h !== hora) },
    }));

  const horariosDisponiveis = gerarHorariosComData(progresso.disponibilidade.dias, progresso.disponibilidade.horas);

  // Sempre que a mentora muda a disponibilidade, isso fica visível publicamente
  useEffect(() => {
    if (!carregado || !session || (progresso.papel !== "mentora" && progresso.papel !== "dona")) return;
    supabase
      .from("mentores_disponibilidade")
      .upsert(
        {
          user_id: session.user.id,
          email: session.user.email,
          dias: progresso.disponibilidade.dias,
          horas: progresso.disponibilidade.horas,
          meses: progresso.disponibilidade.meses,
          atualizado_em: new Date().toISOString(),
        },
        { onConflict: "user_id" }
      )
      .then(() => {})
      .catch(() => {});
  }, [progresso.disponibilidade, progresso.papel, carregado, session]);

  // Sempre que a Comunidade fica desbloqueada, cria/atualiza o perfil público (para o chat)
  useEffect(() => {
    if (!carregado || !session || !progresso.comunidadeDesbloqueada) return;
    supabase
      .from("perfis_comunidade")
      .upsert(
        { user_id: session.user.id, email: session.user.email, atualizado_em: new Date().toISOString() },
        { onConflict: "user_id" }
      )
      .then(() => {})
      .catch(() => {});
  }, [progresso.comunidadeDesbloqueada, carregado, session]);

  const toggleMentora = () =>
    setProgresso((p) => {
      if (p.papel === "dona") return p; // a dona da escola não se rebaixa por engano
      return { ...p, papel: p.papel === "mentora" ? "aluno" : "mentora" };
    });

  const guardarReflexao = (mes, texto) =>
    setProgresso((p) => ({
      ...p,
      reflexoesComunidade: { ...p.reflexoesComunidade, [mes]: texto },
    }));

  const mudarTab = (novaTab) => {
    setTab(novaTab);
    setSecao(null);
  };

  if (!sessaoCarregada) {
    return (
      <>
        <style>{FONTS}</style>
        <div
          className="min-h-screen w-full flex items-center justify-center"
          style={{ backgroundColor: palette.cream, fontFamily: "Inter, sans-serif" }}
        >
          <Brand size="sm" />
        </div>
      </>
    );
  }

  if (modoNovaPassword) {
    return (
      <>
        <style>{FONTS}</style>
        <div style={{ fontFamily: "Inter, sans-serif" }}>
          <style>{`.font-serif { font-family: 'Cormorant Garamond', serif; }`}</style>
          <NovaPasswordScreen onConcluido={() => setModoNovaPassword(false)} />
        </div>
      </>
    );
  }

  if (!session) {
    return (
      <>
        <style>{FONTS}</style>
        <div style={{ fontFamily: "Inter, sans-serif" }}>
          <style>{`.font-serif { font-family: 'Cormorant Garamond', serif; }`}</style>
          {emailEnviado ? (
            <AguardaEmailScreen email={emailEnviado} />
          ) : emailRecuperacao ? (
            <AguardaEmailScreen email={emailRecuperacao} recuperacao />
          ) : (
            <LoginScreen onPedirConfirmacaoEmail={setEmailEnviado} onPedidoRecuperacao={setEmailRecuperacao} />
          )}
        </div>
      </>
    );
  }

  let content;
  if (conversaAberta) {
    content = <ChatPrivadoScreen pessoa={conversaAberta} onBack={() => setConversaAberta(null)} />;
  } else if (certificadoAberto) {
    content = (
      <CertificadoScreen
        curso={certificadoAberto}
        dataConclusao={progresso.cursosConcluidos[certificadoAberto.id]}
        email={session.user.email}
        onBack={() => setCertificadoAberto(null)}
      />
    );
  } else if (clienteAberto) {
    content = (
      <FichaClienteScreen
        cliente={clienteAberto}
        onBack={() => setClienteAberto(null)}
      />
    );
  } else if (cursoAberto) {
    content = (
      <ConteudoDetalhe
        curso={cursoAberto}
        concluido={Boolean(progresso.cursosConcluidos[cursoAberto.id])}
        onToggleConcluido={() => toggleConcluido(cursoAberto.id)}
        onBack={() => setCursoAberto(null)}
      />
    );
  } else if (secao === "aluno") {
    content = (
      <AreaAlunoScreen
        onBack={() => setSecao(null)}
        onOpenCurso={setCursoAberto}
        cursosConcluidos={progresso.cursosConcluidos}
        materiaisDesbloqueados={progresso.materiaisDesbloqueados}
        onVerCertificado={setCertificadoAberto}
      />
    );
  } else if (secao === "comunidade") {
    content = progresso.comunidadeDesbloqueada ? (
      <ComunidadeScreen
        onBack={() => setSecao(null)}
        onOpenCurso={setCursoAberto}
        reflexoes={progresso.reflexoesComunidade}
        onGuardarReflexao={guardarReflexao}
        onAbrirChat={() => setSecao("chat-comunidade")}
        onAbrirMensagens={() => setSecao("mensagens")}
      />
    ) : (
      <ComunidadeBloqueada onBack={() => setSecao(null)} onDesbloquear={desbloquearComunidade} />
    );
  } else if (secao === "chat-comunidade") {
    content = <ChatComunidadeScreen onBack={() => setSecao("comunidade")} />;
  } else if (secao === "mensagens") {
    content = <MensagensListaScreen onBack={() => setSecao("comunidade")} onAbrirConversa={setConversaAberta} />;
  } else if (secao === "workshops") {
    content = <WorkshopsScreen onBack={() => setSecao(null)} inscricoes={progresso.inscricoesWorkshops} onToggleInscricao={toggleInscricao} />;
  } else if (secao === "podcast") {
    content = <PodcastScreen onBack={() => setSecao(null)} />;
  } else if (secao === "formacao") {
    content = <FormacaoScreen onBack={() => setSecao(null)} onOpenCurso={setCursoAberto} cursosConcluidos={progresso.cursosConcluidos} />;
  } else if (secao === "escola-lideranca") {
    content = <FormacaoScreen onBack={() => setSecao(null)} onOpenCurso={setCursoAberto} cursosConcluidos={progresso.cursosConcluidos} escolaFixa="lideranca" />;
  } else if (secao === "escola-ser") {
    content = <FormacaoScreen onBack={() => setSecao(null)} onOpenCurso={setCursoAberto} cursosConcluidos={progresso.cursosConcluidos} escolaFixa="ser" />;
  } else if (secao === "material") {
    content = (
      <MaterialDidaticoScreen
        onBack={() => setSecao(null)}
        desbloqueados={progresso.materiaisDesbloqueados}
        onDesbloquear={desbloquearMaterial}
        acessoTotal={progresso.papel === "dona"}
      />
    );
  } else if (secao === "marcar") {
    content = (
      <MarcarSessaoScreen
        onBack={() => setSecao(null)}
        onConfirmar={registarSessao}
      />
    );
  } else if (secao === "disponibilidade") {
    content = (
      <DisponibilidadeScreen
        onBack={() => setSecao(null)}
        disponibilidade={progresso.disponibilidade}
        onToggleDia={toggleDiaDisponivel}
        onAdicionarHora={adicionarHora}
        onRemoverHora={removerHora}
        onToggleMes={toggleMesDisponivel}
      />
    );
  } else if (secao === "painel-mentora") {
    content = (
      <PainelMentoraScreen
        onBack={() => setSecao(null)}
        progresso={progresso}
        onVerDashboard={() => setSecao("dashboard-mentora")}
      />
    );
  } else if (secao === "dashboard-mentora") {
    content = (
      <DashboardMentoraScreen
        onBack={() => setSecao("painel-mentora")}
        onAbrirCliente={(c) => setClienteAberto(c)}
      />
    );
  } else if (tab === "inicio") {
    content = <InicioScreen onOpen={setSecao} email={session.user.email} />;
  } else if (tab === "explorar") {
    content = <ExplorarScreen onOpen={setSecao} />;
  } else if (tab === "agenda") {
    content = <AgendaScreen inscricoesWorkshops={progresso.inscricoesWorkshops} sessoesMarcadas={progresso.sessoesMarcadas} />;
  } else if (tab === "perfil") {
    content = (
      <PerfilScreen
        onVerAreaAluno={() => { setTab("inicio"); setSecao("aluno"); }}
        onVerDisponibilidade={() => { setTab("perfil"); setSecao("disponibilidade"); }}
        onVerPainelMentora={() => { setTab("perfil"); setSecao("painel-mentora"); }}
        papel={progresso.papel}
        onToggleMentora={toggleMentora}
        onSair={() => supabase.auth.signOut()}
        email={session.user.email}
      />
    );
  }

  return (
    <>
      <style>{FONTS}</style>
      <style>{`.font-serif { font-family: 'Cormorant Garamond', serif; }`}</style>
      <div className="min-h-screen w-full flex justify-center" style={{ backgroundColor: palette.cream, fontFamily: "Inter, sans-serif" }}>
        <div className="w-full max-w-md relative" style={{ backgroundColor: palette.creamSoft }}>
          {content}
          {!cursoAberto && <BottomNav active={tab} onChange={mudarTab} />}
        </div>
      </div>
    </>
  );
}
